mermaid.source:
flowchart LR
    A["Stored source revisions"] --> B{"Event time <= grid time?"}
    B -->|No| C["No history"]
    B -->|Yes| D{"Availability time <= query time?"}
    D -->|No| E["Not yet available"]
    D -->|Yes| F["Latest event, latest available revision"]
    F --> G{"Source age <= expiry?"}
    G -->|Yes| H["Exact or carried value"]
    G -->|No| I["Stale missing value with lineage"]

flowchart LR
    A["Target plus evaluation cutoff"] --> B{"Exact event?"}
    B -->|Yes| C{"Exact record available?"}
    C -->|No| D["exact_not_available"]
    C -->|Yes| E["exact observed quote"]
    B -->|No| F{"Same-partition bracket?"}
    F -->|No| G["unavailable; no extrapolation"]
    F -->|Yes| H{"Gap within inclusive limit?"}
    H -->|No| I["gap_too_wide"]
    H -->|Yes| J{"Both endpoints available?"}
    J -->|No| K["block at knowledge boundary"]
    J -->|Yes| L["linear derived quote; observable=false"]

flowchart LR
    A["CRSP CIZ 2.0 row and release"] --> B{"DlyCumFacShr or MthCumFacShr?"}
    B -->|No| X["Reject field substitution"]
    B -->|Yes| C{"CRSP factor and raw quantity present?"}
    C -->|No| M["Return explicit missing status"]
    C -->|Yes| D{"Monthly volume with mixed basis?"}
    D -->|Yes| R["Require licensed daily reconstruction"]
    D -->|No| E["Multiply by CRSP share factor"]
    E --> F["Round once at 12 decimals"]
    F --> G["Retain CRSP release, basis, and status"]

flowchart LR
    A["Raw issue-count request"] --> B{"Supported variant?"}
    B -- "No" --> U["Unsupported; ABI null"]
    B -- "Yes" --> C["Keep records effective and available by decision time"]
    C --> D{"Any causal record?"}
    D -- "No" --> I["Incomplete; ABI null"]
    D -- "Yes" --> E{"One identity and contiguous lineage?"}
    E -- "No" --> M["Ambiguous; ABI null"]
    E -- "Yes" --> F{"Current record complete and not cancelled?"}
    F -- "No" --> I
    F -- "Yes" --> G["Net Advances = A - D"]
    G --> H["Raw ABI = absolute value of Net Advances"]
    H --> R["Resolved; retain counts, sign, clocks, revision, finality"]

flowchart TD
    A["Receive ordered observation x_t"] --> B{"Window is a positive integer and x_t is finite?"}
    B -- "No" --> X["Reject input"]
    B -- "Yes" --> C["Add x_t to rolling sum"]
    C --> D{"More than n observations?"}
    D -- "Yes" --> E["Subtract outgoing x_(t-n)"]
    D -- "No" --> F{"At least n observations?"}
    E --> F
    F -- "No" --> G["Emit null · warming"]
    F -- "Yes" --> H["Emit rolling_sum / n · ready"]
